commands.cmd:
Y="${RR:?}/syft-use"; mkdir "$Y" && E="$HOME/.local/share/codex-ecosystem/sdk-py313" && SYFT_CHECK_FOR_APP_UPDATE=false syft scan "dir:$E" --source-name sdk-py313 -q -o "syft-json=$Y/sdk.syft.json" -o "cyclonedx-json=$Y/sdk.cdx.json" && uv pip freeze --python "$E/bin/python" > "$Y/freeze.txt" && python3 -c "
import json,re,sys
n=lambda s:re.sub(r'[-_.]+','-',s).lower()
d=json.load(open(sys.argv[1]));x=json.load(open(sys.argv[2]))
sb={(n(a['name']),a['version']) for a in d['artifacts'] if a['type']=='python'}
fr={(n(l.split('==')[0]),l.split('==')[1].strip()) for l in open(sys.argv[3]) if '==' in l}
cx={(n(k['name']),k['version']) for k in x.get('components',[]) if k.get('type')=='library'}
p={a['name']:a.get('purl') for a in d['artifacts'] if a['name'] in ('alpaca-py','duckdb')}
print('syft-json python packages',len(sb),'| CycloneDX library components',len(cx),'| installed distributions (uv pip freeze)',len(fr),'| identical name/version sets:',sb==fr==cx,'| purls',p)
raise SystemExit(0 if sb and sb==fr==cx else 1)
" "$Y/sdk.syft.json" "$Y/sdk.cdx.json" "$Y/freeze.txt"
